const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Tshopo Province geometry (approximate bounds around Kisangani)
  // Kisangani is approximately at 0.52°N, 25.19°E
  // Tshopo province covers a large area in northeastern DRC
  const tshopo = ee.Geometry.Polygon([
    [[23.0, -1.0], [27.0, -1.0], [27.0, 2.0], [23.0, 2.0], [23.0, -1.0]]
  ]);

  // 2. Load Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // 3. Extract loss year band (values 1-23 represent years 2001-2023)
  const lossYear = hansen.select('lossyear');

  // 4. Create mask for loss since 2001 (lossyear > 0)
  const lossSince2001 = lossYear.gt(0);

  // 5. Calculate pixel count to check for valid data
  const pixelCount = lossSince2001.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: tshopo,
    scale: 3000,
    maxPixels: 1e9
  });

  const count = await pixelCount.get('lossyear').getInfo();

  if (count === null || count === undefined) {
    console.log("Calculation failed - no valid result");
    console.log("<answer>C3</answer>");
    return;
  }

  if (count === 0) {
    console.log("No tree cover loss detected (0 pixels)");
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Calculate area of loss in square kilometers
  // Each pixel is ~30m x 30m = 900 m² = 0.0009 km²
  const pixelAreaKm2 = 0.0009;
  const lossAreaKm2 = count * pixelAreaKm2;

  // 7. Validate result
  if (lossAreaKm2 < 0 || isNaN(lossAreaKm2)) {
    console.log("Invalid calculation result");
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Print evidence and answer
  console.log(`Tree cover loss pixels: ${Math.round(count)}`);
  console.log(`Total tree cover loss area: ${lossAreaKm2.toFixed(2)} km²`);
  console.log(`Threshold: 15,000 km²`);

  if (lossAreaKm2 < 15000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
